import React,{useEffect,useRef,useState} from 'react'; import './Contact.css'; import contactImg from '../Assets/contact.jpg'; import { FiArrowUpRight,FiMail,FiPhone,FiMapPin } from 'react-icons/fi';
const Contact=()=>{const ref=useRef(null);const [visible,setVisible]=useState(false);useEffect(()=>{const observer=new IntersectionObserver(([entry])=>{if(entry.isIntersecting){setVisible(true);observer.disconnect()}},{threshold:.14});if(ref.current)observer.observe(ref.current);return()=>observer.disconnect()},[]);return <section className={`contact-section ${visible?'is-visible':''}`} id="contact" ref={ref}><div className="contact-shell"><div className="contact-copy"><p className="section-kicker">Start a conversation</p><h2>Let’s make your<br/><span>next move matter.</span></h2><p className="contact-intro">Have an idea, a product challenge, or a project in motion? Tell us where you’re headed and we’ll help find the right way forward.</p><a className="contact-cta" href="mailto:info@buildwebcanada.com">Tell us about your project <FiArrowUpRight/></a><div className="contact-details"><a href="mailto:info@buildwebcanada.com"><FiMail/> info@buildwebcanada.com</a><a href="tel:+17789969060"><FiPhone/> +1 (778) 996 9060</a><span><FiMapPin/> Vancouver, BC · Working worldwide</span></div></div><div className="contact-visual"><div className="visual-orb"/><img src={contactImg} alt="BuildWebCanada is ready to talk"/><div className="response-note"><span/> Usually replies within 1–2 business days</div></div></div></section>};
export default Contact;
